from collections import deque
import json

# Load demos to verify transform
with open("/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u011/system/state/workspace/programs/task-770f2daf.json", "r") as f:
    demo_data = json.load(f)

demos = demo_data["demos"]
for i, demo in enumerate(demos):
    print(f"Demo {i}: input shape {demo['input'].shape}, output shape {demo['output'].shape}")
    print(f"  Input unique values: {set(v for row in demo['input'] for v in row)}")
    print(f"  Output unique values: {set(v for row in demo['output'] for v in row)}")

# My hypothesis: 4-connectivity flood fill through 0s from source 3s (treating 5 as wall)
# But wait - in demo, background is 5, so 5s shouldn't be blocked!

# Actually let me reconsider: The demo input has 5s as majority (walls?) and 0s as sparse.
# 3s propagate through 0s. Let's test 4-connect through 0s:
def transform(grid):
    rows, cols = len(grid), len(grid[0])

    # Identify the special value (most frequent) and empty cells (least frequent, not background)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1

    # Most frequent = 5 (background/wall), next = 0 (fillable), least = 3 (source)
    sorted_by_count = sorted(counts.items(), key=lambda x: x[1], reverse=True)

    background = sorted_by_count[0][0]  # 5
    fillable_val = background if background not in [[3,2,0],[2,3,0],[3,0,2]] else sorted_by_count[1][0]  # 0
    special_val = sorted_by_count[-1][0]  # 3

    # 4-connectivity flood fill through fillable cells from special cells
    visited = set()
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == special_val:
                visited.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == fillable_val and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    # Create output
    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if (r, c) in visited:
                row.append(special_val)
            else:
                row.append(grid[r][c])
        result.append(row)

    return result

# Test against demo
input_demo = demos[0]['input']
output_demo = demos[0]['output']
result = transform(input_demo)

# Compare
match = True
for r in range(len(input_demo)):
    for c in range(len(input_demo[0])):
        if result[r][c] != output_demo[r][c]:
            print(f"Mismatch at ({r},{c}): got {result[r][c]}, expected {output_demo[r][c]}")
            match = False

