    background = sorted_by_count[0][0]
    fillable_val = sorted_by_count[1][0]
    special_val = sorted_by_count[-1][0]

    visited = set()
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == special_val:
                visited.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == fillable_val and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

