def bfs_distance_from_3s(grid, pos):
    """Calculate 4-connected distance from nearest 3"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = deque()

    # Find all 3s
    start_positions = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                start_positions.append((r, c))
                visited.add((r, c))

    # BFS from all 3s simultaneously
    while queue:
        cr, cc = queue.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))
                continue

    # Get distances by BFS layers
    dist = {p: float('inf') for p in visited}
    dist[start_positions] = 0

    final_queue = deque(start_positions)
    while final_queue:
        cr, cc = final_queue.popleft()
        if (cr, cc) == pos:
            return dist[(cr, cc)]
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) in visited:
                dist[(nr, nc)] = dist[(cr, cc)] + 1  
                if (nr, nc) != pos and (nr, nc) not in dist:
                    final_queue.append((nr, nc))

    return dist.get(pos, float('inf'))

