from collections import deque, Counter

input_demo = demos[0]['input']
output_demo = demos[0]['output']

def bfs_distance_3s(grid, pos):
    """Get shortest 4-connected distance from any 3"""
    rows, cols = len(grid), len(grid[0])
    dist = {((r, c)): -1 for r in range(rows) for c in range(cols)}

    start_nodes = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 3]
    for s in start_nodes:
        dist[s] = 0

    queue = deque(start_nodes)
    while queue:
        curr = queue.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = curr[0] + dr, curr[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and dist[(nr, nc)] == -1 and grid[nr][nc] == 0:
                dist[(nr, nc)] = dist[curr] + 1
                queue.append((nr, nc))

    return dist.get(pos, float('inf'))

